constraints:
1 <= N, M <= 10^{3}
	1 <= mat[i][j] <= 10^{6}

expected time complexity: O(N*M)
expected auxiliary space: O(N*M)

standard_solution_code:
class Solution:

	def water_flow(self, grid, n, m):

		def dfs(i, j, ref_set, prev):
			if i < 0 or j < 0 or i >= n or (j >= m) or (grid[i][j] < prev) or ((i, j) in ref_set):
				return 0
			ref_set.add((i, j))
			dfs(i + 1, j, ref_set, grid[i][j])
			dfs(i - 1, j, ref_set, grid[i][j])
			dfs(i, j + 1, ref_set, grid[i][j])
			dfs(i, j - 1, ref_set, grid[i][j])
		n = len(grid)
		m = len(grid[0])
		pacific = set()
		atlantic = set()
		for i in range(n):
			dfs(i, 0, pacific, grid[i][0])
			dfs(i, m - 1, atlantic, grid[i][m - 1])
		for i in range(m):
			dfs(0, i, pacific, grid[0][i])
			dfs(n - 1, i, atlantic, grid[n - 1][i])
		common_list = set(pacific).intersection(atlantic)
		return len(common_list)
